edits.oldText:
if (Platform.isLinux && cfg is CassetteScreenConfig cassetteCfg) ...[
  _Cycle(
    'void-settings-cassette-variant',
    'color scheme',
    cassetteVariantMeta[cassetteCfg.variant]!.label,
    () {
      final next = CassetteVariant.values[
          (cassetteCfg.variant.index + 1) % CassetteVariant.values.length];
      settings.saveScreenConfig(cassetteCfg.copyWith(variant: next));
    },
  ),
  textSize('void-settings-cassette-text-size', cassetteCfg.textScale,
      (v) => cassetteCfg.copyWith(textScale: v)),
  _Toggle(
    'void-settings-cassette-haptics',
    'haptics',
    cassetteCfg.hapticsEnabled,
    () => settings.saveScreenConfig(cassetteCfg.copyWith(
        hapticsEnabled: !cassetteCfg.hapticsEnabled)),
  ),
],

